const proposalCopy={
es:['Rainbow Park, un lugar para comenzar.','Una colección de lotes residenciales de Next Fraga en Rainbow Park, Ocala. Parcelas en un vecindario existente, con opciones de vivienda para explorar.','Conoce su ubicación, compara los modelos Utah y Bell y prepara tu consulta con la información que te interesa.','Conocer los lotes','Explorar los lotes','Explorar los datos y proyectos en esta página','¿Qué te gustaría explorar?','Ver más sobre inversión'],
en:['Rainbow Park, a place to begin.','A collection of residential lots from Next Fraga in Rainbow Park, Ocala. Parcels in an existing neighborhood, with home options to explore.','Explore the locations, compare the Utah and Bell models, and prepare your inquiry with the information that matters to you.','Discover the lots','Explore the lots','Explore the data and projects on this page','What would you like to explore?','More about investment'],
pt:['Rainbow Park, um lugar para começar.','Uma coleção de lotes residenciais da Next Fraga em Rainbow Park, Ocala. Terrenos em um bairro existente, com opções de moradia para explorar.','Conheça a localização, compare os modelos Utah e Bell e prepare sua consulta com as informações que interessam a você.','Conhecer os lotes','Explorar os lotes','Explorar os dados e projetos nesta página','O que você gostaria de explorar?','Saiba mais sobre investimento']};
const proposalSelectors=['#project-intro-title','.project-introduction p','.intro-secondary','.intro-link','.hero .enter-orbit span','.investment-detail>summary','.consultation-title','.investment-opening .investment-button'];
function translateProposal(){const lang=(document.documentElement.lang||'es').slice(0,2),copy=proposalCopy[lang]||proposalCopy.es;proposalSelectors.forEach((selector,i)=>{const el=document.querySelector(selector);if(!el)return;if(i===0&&lang==='es'){el.innerHTML='Rainbow Park,<br>un lugar para comenzar.';return;}if(i===7){el.firstChild.textContent=copy[i]+' ';}else if(el.textContent!==copy[i])el.textContent=copy[i];});}
new MutationObserver(translateProposal).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});
translateProposal();
